-- Independent Dadyoom teaching supports, not claims about the contents of official books.
-- Idempotent: update only genuinely empty published lessons; add each origin/type once.
DO $dadyoom$
DECLARE
  r RECORD;
  target_id uuid;
  target_content text;
BEGIN
  FOR r IN SELECT * FROM jsonb_to_recordset('[{"n":11,"skill":"استنتاج العاطفة من شاهد شعري موثق","passage":"درس «أنت الهوى» يتطلب القصيدة الأصلية لفهم عاطفة الشاعر وتحديد الأبيات من 1 إلى 7 للحفظ. نص تدريبي مستقل: «أحب أرضي حين تجمعني بالأهل وتذكرني بذكريات الطفولة». نستدل على المحبة من لفظ «أحب» دون نسبته إلى القصيدة.","prompt":"ما اللفظ الذي يدل مباشرة على المحبة؟","correct":"أحب","w1":"حين","w2":"تجمعني","w3":"بذكريات","practice":"من النص الأصلي المرخص استخرج بيتًا واحدًا يعبر عن عاطفة محددة واشرح اللفظ الدال، ثم راجع الحفظ مع المعلم."},{"n":12,"skill":"الرسالة الأسرية والنصيحة بالحجة","passage":"نص مستقل: «قال الأب لولده: لا تجعل خطأ اليوم سببًا للتوقف؛ راجع عملك وحاول ثانية». يرتبط النصح بتقديم سبب وخطوة عملية لا بالأمر المجرد؛ ولا نزعم أنه مقتبس من قراءة «إلى ولدي».","prompt":"بأي فعل اقترح الأب تحسين الأداء؟","correct":"مراجعة العمل والمحاولة ثانية","w1":"التوقف نهائيًا","w2":"إخفاء الخطأ","w3":"لوم الآخرين","practice":"اكتب فقرة نصيحة إلى أخ أصغر تتضمن قيمة ودليلًا ومثالًا عمليًا دون وعظ مبهم."},{"n":13,"skill":"القيمة الأخلاقية والصورة التعبيرية","passage":"لا يُنسب إلى قصيدة «كن بلسما» أي بيت غير موثق. في عبارة تدريبية مستقلة «الكلمة الطيبة بلسم للقلوب» تُستخدم صورة تقرّب أثر الكلمة في تهدئة الآخرين، وتحتاج دراسة الأبيات 1 إلى 6 إلى نص القصيدة الأصلي.","prompt":"ماذا توحي كلمة «بلسم» في العبارة التدريبية؟","correct":"التخفيف والمواساة","w1":"الضرر","w2":"الخوف","w3":"الانقطاع","practice":"اختر صورة شعرية موثقة من القصيدة واشرح أثرها، ثم اكتب مثالًا نثريًا أصليًا يحمل المعنى نفسه."},{"n":14,"skill":"المقارنة بين الماضي والحاضر دون اختلاق نص","passage":"لفهم «لا تسل كيف كنا» يجب قراءة الأبيات الأصلية. تدريب مستقل: «كانت القرية صغيرة طرقها ترابية؛ واليوم امتدت فيها مدارس ومكتبات». نميز بين الزمنين ونقارن بمعلومات واضحة، دون جعل الجمل أبياتًا للقصيدة.","prompt":"أي عبارة تشير إلى الحاضر؟","correct":"امتدت فيها مدارس ومكتبات","w1":"كانت القرية صغيرة","w2":"طرقها ترابية قديمًا","w3":"في ذلك الزمان","practice":"اكتب مقارنة من ستة أسطر بين نشاط قديم وحديث، مستخدمًا أمثلة يمكن التحقق منها دون تعميم."},{"n":15,"skill":"الاستدلال والتفكر دون نسبة قول للنص الشرعي","passage":"في قراءة بعنوان «من دلائل قدرة الله» يلزم الاعتماد على نص المصدر لتحديد الآيات أو الأفكار المقررة. نموذج مستقل: «تتغير الفصول وفق نظام يلاحظه الإنسان في النبات والطقس». هذه عبارة علمية عامة وليست آية ولا حديثًا؛ نميز المشاهدة من الحكم الديني الموثق.","prompt":"ما المثال المشاهد في النص المستقل؟","correct":"تغير الفصول وأثره في النبات","w1":"توقف حركة الكواكب","w2":"تغير اللغة كل ساعة","w3":"اختفاء الليل تمامًا","practice":"ارجع إلى النص المدرسي الموثق وحدد دليلًا ورد فيه، ثم فسّر معناه دون إضافة أقوال غير متحققة."},{"n":16,"skill":"خطاب الشباب وتحويل الفكرة إلى مبادرة","passage":"في رسالة مستقلة: «يا شباب الوطن، خصصوا يومًا لتبادل الكتب حتى ينتفع الجميع». النداء يحدد الجمهور، والفعل «خصصوا» دعوة إلى مبادرة قابلة للتنفيذ. لا يمثل هذا النص القصيدة أو المقال الأصلي «يا شباب العرب».","prompt":"ما المبادرة المقترحة في النموذج؟","correct":"تبادل الكتب","w1":"إغلاق المكتبات","w2":"إيقاف الأنشطة","w3":"منع القراءة","practice":"اكتب رسالة قصيرة إلى الشباب تدعو لمبادرة نافعة، مع هدف وخطوتين لقياس النجاح."},{"n":20,"skill":"إدراك القيم الإنسانية وتوثيق الشعر","passage":"لا يمكن فهم قصيدة «إن الكرام قليل» أو حفظ الأبيات 1 إلى 6 دون النص الأصلي. نموذج مستقل: «ساعدت منى جارتها عندما احتاجت إلى دواء، ولم تنتظر شكرًا». يدل الفعل على الكرم والمروءة، وهذا ليس بيتًا شعريًا.","prompt":"ما السلوك الذي يدل على الكرم في النموذج؟","correct":"مساعدة الجارة دون انتظار مقابل","w1":"تجاهل الحاجة","w2":"طلب مكافأة أولًا","w3":"الاعتذار دون فعل","practice":"اكتب شرحًا لقيمة أخلاقية في بيت موثق من القصيدة، مع موقف عملي مستقل يوضحها."},{"n":21,"skill":"التفريق بين الملاحظة العلمية والتخمين","passage":"مقطع مستقل: «راقب الباحث حركة ظل عمود خلال النهار، وسجل اختلاف طوله في أوقات متتابعة». الملاحظة القابلة للقياس تختلف عن التخمين؛ ولا نقدمها على أنها من نص «الإنسان وأسرار الكون».","prompt":"ما البيانات التي سجلها الباحث؟","correct":"طول الظل في أوقات مختلفة","w1":"لون حقيبته","w2":"نوع الحلوى","w3":"عدد مقاعد الصف","practice":"صغ سؤالًا علميًا بسيطًا، واذكر كيف تجمع بيانات مناسبة له دون ادعاء نتائج غير ملاحظة."},{"n":22,"skill":"تحديد أثر التردد في القرار","passage":"نموذج مستقل: «وقف عمر عند باب النادي، وفكر في العودة، ثم تذكر أنه تدرب أسبوعًا وقرر الدخول». يظهر التردد في الوقوف والتفكير بالعودة، والحسم في الفعل الأخير. لا تنسب الأحداث إلى درس «التردد».","prompt":"أي فعل يدل على اتخاذ القرار بعد تردد؟","correct":"قرر الدخول","w1":"وقف عند الباب","w2":"فكر في العودة","w3":"تذكر التدريب","practice":"اكتب موقفًا من خمسة أسطر يوضح خيارين وسبب التردد ثم قرارًا معللًا."},{"n":23,"skill":"تحليل القيمة والدليل في النص الشعري","passage":"تحتاج قراءة «قيم عربية» إلى الأبيات الحقيقية قبل نسبة أي معنى للشاعر. في مقطع مستقل: «حفظ التاجر وعده رغم صعوبة الطريق، فأوصل الأمانة في موعدها». نستدل من الوفاء بالوعد على قيمة الأمانة.","prompt":"أي فعل يجسد الأمانة في المثال؟","correct":"حفظ الوعد وإيصال الأمانة","w1":"ترك المهمة","w2":"نسيان الوعد","w3":"إخفاء البضاعة","practice":"استخرج بيتًا موثقًا من القصيدة يبرز قيمة محددة، ثم ناقش تطبيقها في موقف معاصر."},{"n":24,"skill":"المروءة والوفاء في موقف إنساني","passage":"مقطع أصلي: «كان المسافر بحاجة إلى مأوى، فدعاه أهل القرية إلى الاستراحة، ثم ساعدوه في متابعة الطريق». نحدد فعل المروءة ونتيجته من النص، ولا نعد هذه قصة درس «مروءة ووفاء» الواردة في الكتاب.","prompt":"ما الذي فعلته القرية لمساعدة المسافر؟","correct":"قدمت له مكانًا للراحة ثم ساعدته","w1":"تركته بلا إرشاد","w2":"منعته من الماء","w3":"طلبت منه العودة","practice":"اكتب موقفًا تظهر فيه مروءة شخصية ووفاؤها، مستخدمًا حدثًا واضحًا ونتيجة مترتبة عليه."}]'::jsonb) AS x(
    n integer,skill text,passage text,prompt text,correct text,w1 text,w2 text,w3 text,practice text
  ) LOOP
    SELECT l.id,l.content INTO STRICT target_id,target_content
    FROM public.lessons l
    JOIN public.units u ON u.id=l.unit_id
    JOIN public.grades g ON g.id=u.grade_id AND g.grade_number=9
    JOIN public.curricula cu ON cu.id=g.curriculum_id AND cu.academic_year='2026-2027'
    JOIN public.countries c ON c.id=cu.country_id AND c.code='BH'
    WHERE u.title='القراءة والنصوص' AND u.semester=1 AND l.sort_order=r.n AND l.status='published'
    FOR UPDATE OF l;
    IF coalesce(trim(target_content),'')='' OR (target_content LIKE 'يتناول هذا الدرس موضوع%' AND char_length(target_content)<350) THEN
      UPDATE public.lessons SET
        content='ضاديوم — إثراء مستقل أصلي للصف الثامن، الفصل الأول. لا يمثل النص الوزاري الأصلي ولا يثبت مطابقة العنوان للمصدر.'||E'\n\n'||
          'المهارة: '||r.skill||E'\n\n'||
          'النموذج التعليمي والشرح: '||r.passage||E'\n\n'||
          'أهداف التعلم: يحدد المتعلم شاهدًا صحيحًا ويشرح دلالته، ويميّز بين الفكرة والدليل، ثم ينتج كتابة مناسبة للمهارة.'||E'\n\n'||
          'سؤال الفهم: '||r.prompt||E'\n\n'||
          'التطبيق الكتابي: '||r.practice||E'\n\n'||
          'التمايز: المبتدئ يحصل على كلمات مفتاحية وبداية جملة؛ المتوسط يجيب بدليل مستقل؛ المتقدم يقارن بين صياغتين ويبرر تحسيناته.'||E'\n\n'||
          'مراجعة المعلم: تحقق من صحة الاستدلال والإملاء وعلامات الترقيم والترابط. لا تُمنح درجة جودة تلقائية لمجرد تسليم المهمة.'||E'\n\n'||
          'تنبيه المصدر: راجع العنوان المستورد والكتاب الرسمي قبل وصف هذا التدريب بأنه مطابق للمنهج.'||E'\n\n'||'المدخل السابق المحفوظ: '||coalesce(target_content,''),
        updated_at=now()
      WHERE id=target_id;
    END IF;
    IF EXISTS (SELECT 1 FROM public.lessons WHERE id=target_id AND content LIKE 'ضاديوم — إثراء مستقل أصلي للصف الثامن%') THEN
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'فهم النص الإثرائي','multiple_choice','assessment',r.prompt,
        jsonb_build_object('origin','DADYOOM_BH_G9_T1_READING_11_20261008','notOfficialBook',true,'ocrReview','pending','options',jsonb_build_array(r.correct,r.w1,r.w2,r.w3)),
        jsonb_build_object('correct',r.correct),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='multiple_choice' AND content->>'origin'='DADYOOM_BH_G9_T1_READING_11_20261008');
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'كتابة تطبيقية بمراجعة المعلم','writing','practice',r.practice,
        jsonb_build_object('origin','DADYOOM_BH_G9_T1_READING_11_20261008','notOfficialBook',true,'humanReviewRequired',true,'text',r.practice,'skillQualityAutoVerified',false),
        jsonb_build_object('grading_mode','completion_only_reference','model_answer','لا تكفي المطابقة النصية؛ يصحح المعلم ملاءمة الأفكار والدليل والترابط.'),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='writing' AND content->>'origin'='DADYOOM_BH_G9_T1_READING_11_20261008');
    END IF;
  END LOOP;
END
$dadyoom$;